import{_ as e,o as i,c as n,a3 as t}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"私有化部署与容量评估","description":"从数据、模型、硬件、推理拓扑、流量模型、容量计算、高可用和验收评估私有模型服务。","frontmatter":{"title":"私有化部署与容量评估","description":"从数据、模型、硬件、推理拓扑、流量模型、容量计算、高可用和验收评估私有模型服务。","verified_at":"2026-07-31","source":["https://docs.vllm.ai/en/latest/serving/distributed_serving.html","https://kubernetes.io/docs/concepts/workloads/controllers/deployment/","https://kubernetes.io/docs/concepts/configuration/manage-resources-containers/","https://sre.google/sre-book/handling-overload/"],"article":{"type":"decision","structure":"decision"}},"headers":[],"relativePath":"py-agent/quality/model-serving-adaptation/private-deployment-capacity-planning.md","filePath":"py-agent/quality/model-serving-adaptation/private-deployment-capacity-planning.md","lastUpdated":1785589115000}'),l={name:"py-agent/quality/model-serving-adaptation/private-deployment-capacity-planning.md"};function s(r,a,o,p,h,d){return i(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="私有化部署与容量评估" tabindex="-1">私有化部署与容量评估 <a class="header-anchor" href="#私有化部署与容量评估" aria-label="Permalink to &quot;私有化部署与容量评估&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>私有化部署的决策不应只问“需要几张 GPU”。先要确认数据和控制要求是否真的要求自托管，再把模型制品、推理引擎、硬件、流量、SLO、人员和恢复能力放进同一容量模型。</p><h2 id="_1-决策背景" tabindex="-1">1. 决策背景 <a class="header-anchor" href="#_1-决策背景" aria-label="Permalink to &quot;1. 决策背景&quot;">​</a></h2><h3 id="_1-1-常见动机" tabindex="-1">1.1 常见动机 <a class="header-anchor" href="#_1-1-常见动机" aria-label="Permalink to &quot;1.1 常见动机&quot;">​</a></h3><ul><li>数据不能离开指定网络或地域；</li><li>需要固定权重、模板和运行版本；</li><li>流量稳定且自建成本可能更低；</li><li>需要特殊模型、Adapter、量化或硬件；</li><li>需要离线、边缘或低网络时延运行。</li></ul><h3 id="_1-2-不充分的动机" tabindex="-1">1.2 不充分的动机 <a class="header-anchor" href="#_1-2-不充分的动机" aria-label="Permalink to &quot;1.2 不充分的动机&quot;">​</a></h3><p>“开源免费”忽略硬件、机房、网络、人员、电力、故障和机会成本；“数据不发第三方”也不意味着内部访问、日志和供应链自动安全。</p><h2 id="_2-约束与决策标准" tabindex="-1">2. 约束与决策标准 <a class="header-anchor" href="#_2-约束与决策标准" aria-label="Permalink to &quot;2. 约束与决策标准&quot;">​</a></h2><h3 id="_2-1-能力与质量" tabindex="-1">2.1 能力与质量 <a class="header-anchor" href="#_2-1-能力与质量" aria-label="Permalink to &quot;2.1 能力与质量&quot;">​</a></h3><p>候选模型必须在领域任务、工具调用、结构化输出、安全和语言上达到阈值。若模型本身不满足目标，增加 GPU 不能解决质量问题。</p><h3 id="_2-2-数据与合规" tabindex="-1">2.2 数据与合规 <a class="header-anchor" href="#_2-2-数据与合规" aria-label="Permalink to &quot;2.2 数据与合规&quot;">​</a></h3><p>明确数据分类、地域、网络隔离、日志保留、加密、审计和供应链要求。模型权重许可证也可能限制用途或再分发。</p><h3 id="_2-3-slo" tabindex="-1">2.3 SLO <a class="header-anchor" href="#_2-3-slo" aria-label="Permalink to &quot;2.3 SLO&quot;">​</a></h3><p>定义可用性、TTFT、总延迟、吞吐、恢复时间和恢复点。容量规划要满足尾延迟和突发流量，不只满足平均 QPS。</p><h3 id="_2-4-运维能力" tabindex="-1">2.4 运维能力 <a class="header-anchor" href="#_2-4-运维能力" aria-label="Permalink to &quot;2.4 运维能力&quot;">​</a></h3><p>评估 GPU/驱动、容器平台、推理引擎、监控、值班、容量和安全人员。没有能升级 Kernel、诊断 OOM 和恢复服务的团队，自托管风险可能高于托管服务。</p><h2 id="_3-部署候选" tabindex="-1">3. 部署候选 <a class="header-anchor" href="#_3-部署候选" aria-label="Permalink to &quot;3. 部署候选&quot;">​</a></h2><h3 id="_3-1-单机单副本" tabindex="-1">3.1 单机单副本 <a class="header-anchor" href="#_3-1-单机单副本" aria-label="Permalink to &quot;3.1 单机单副本&quot;">​</a></h3><p>适合开发、低流量或模型可在单机容纳的内部任务。故障域单一，不满足高可用。</p><h3 id="_3-2-多卡模型并行" tabindex="-1">3.2 多卡模型并行 <a class="header-anchor" href="#_3-2-多卡模型并行" aria-label="Permalink to &quot;3.2 多卡模型并行&quot;">​</a></h3><p>模型跨多卡加载，解决单卡容量，但一组设备共同构成一个副本；任一关键设备故障可能影响整个副本。需要高速互联和拓扑感知调度。</p><h3 id="_3-3-多副本数据并行" tabindex="-1">3.3 多副本数据并行 <a class="header-anchor" href="#_3-3-多副本数据并行" aria-label="Permalink to &quot;3.3 多副本数据并行&quot;">​</a></h3><p>每个副本独立承载请求，扩展吞吐和可用性。前提是单副本可容纳模型或一个完整模型并行组。</p><h3 id="_3-4-混合托管" tabindex="-1">3.4 混合托管 <a class="header-anchor" href="#_3-4-混合托管" aria-label="Permalink to &quot;3.4 混合托管&quot;">​</a></h3><p>常规敏感流量走私有模型，峰值或特定能力走批准的托管端点。它提高弹性，但路由必须严格执行数据与能力约束，且两种模型都要评测。</p><h2 id="_4-工作负载模型" tabindex="-1">4. 工作负载模型 <a class="header-anchor" href="#_4-工作负载模型" aria-label="Permalink to &quot;4. 工作负载模型&quot;">​</a></h2><h3 id="_4-1-不只记录-qps" tabindex="-1">4.1 不只记录 QPS <a class="header-anchor" href="#_4-1-不只记录-qps" aria-label="Permalink to &quot;4.1 不只记录 QPS&quot;">​</a></h3><p>至少收集：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>requests per second distribution</span></span>
<span class="line"><span>input/output token histograms</span></span>
<span class="line"><span>streaming ratio</span></span>
<span class="line"><span>concurrent sessions</span></span>
<span class="line"><span>tool-wait and cancellation behavior</span></span>
<span class="line"><span>prompt-prefix reuse</span></span>
<span class="line"><span>priority classes</span></span>
<span class="line"><span>daily/weekly seasonality and burst</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>同样 1 QPS，输入 500/输出 100 Token 与输入 30k/输出 2k Token 的容量完全不同。</p><h3 id="_4-2-little-s-law" tabindex="-1">4.2 Little&#39;s Law <a class="header-anchor" href="#_4-2-little-s-law" aria-label="Permalink to &quot;4.2 Little&#39;s Law&quot;">​</a></h3><p>稳定系统近似满足：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>concurrency = arrival_rate * average_time_in_system</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>若每秒 2 个请求，平均在系统停留 5 秒，平均并发约 10。它是平均关系，不能替代尾延迟和突发容量模拟。</p><h3 id="_4-3-token-速率" tabindex="-1">4.3 Token 速率 <a class="header-anchor" href="#_4-3-token-速率" aria-label="Permalink to &quot;4.3 Token 速率&quot;">​</a></h3><p>分别估算 Prefill Token/s 和 Decode Token/s，因为两阶段硬件特性不同。用“每秒请求 × 平均总 Token”做粗估后，必须用真实长度分布压测校准。</p><h2 id="_5-单副本内存预算" tabindex="-1">5. 单副本内存预算 <a class="header-anchor" href="#_5-单副本内存预算" aria-label="Permalink to &quot;5. 单副本内存预算&quot;">​</a></h2><h3 id="_5-1-权重" tabindex="-1">5.1 权重 <a class="header-anchor" href="#_5-1-权重" aria-label="Permalink to &quot;5.1 权重&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>weights ~= parameters * bits / 8 + quantization metadata</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="_5-2-kv-cache" tabindex="-1">5.2 KV Cache <a class="header-anchor" href="#_5-2-kv-cache" aria-label="Permalink to &quot;5.2 KV Cache&quot;">​</a></h3><p>KV Cache 随活动 Token 和模型结构增长，是并发与长上下文的主要容量池。Tensor Parallel 后每卡布局依引擎实现，应从运行指标确认。</p><h3 id="_5-3-其他占用" tabindex="-1">5.3 其他占用 <a class="header-anchor" href="#_5-3-其他占用" aria-label="Permalink to &quot;5.3 其他占用&quot;">​</a></h3><p>包括 CUDA Context、Kernel Workspace、Attention 临时张量、CUDA Graph、Tokenizer/CPU 内存、通信缓冲和碎片。必须保留安全余量，不能把显存配置到理论 100%。</p><h3 id="_5-4-预热峰值" tabindex="-1">5.4 预热峰值 <a class="header-anchor" href="#_5-4-预热峰值" aria-label="Permalink to &quot;5.4 预热峰值&quot;">​</a></h3><p>启动、图捕获和模型更新可能出现不同于稳定运行的峰值。滚动更新时新旧副本同时存在，也需要额外集群容量。</p><h2 id="_6-吞吐与并发容量" tabindex="-1">6. 吞吐与并发容量 <a class="header-anchor" href="#_6-吞吐与并发容量" aria-label="Permalink to &quot;6. 吞吐与并发容量&quot;">​</a></h2><h3 id="_6-1-基准一副本" tabindex="-1">6.1 基准一副本 <a class="header-anchor" href="#_6-1-基准一副本" aria-label="Permalink to &quot;6.1 基准一副本&quot;">​</a></h3><p>在目标硬件上，用真实输入/输出长度和并发扫描得到：最大 Goodput、TTFT/TPOT、KV Cache 使用、OOM 边界和功耗。Goodput 是满足 SLO 的吞吐，比峰值 Tokens/s 更适合规划。</p><h3 id="_6-2-计算副本" tabindex="-1">6.2 计算副本 <a class="header-anchor" href="#_6-2-计算副本" aria-label="Permalink to &quot;6.2 计算副本&quot;">​</a></h3><p>粗略计算：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>required_replicas = ceil(peak_goodput / safe_goodput_per_replica)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><code>safe_goodput</code> 应低于实验极限并保留故障、抖动和增长余量。还需满足 N+1：失去一个副本或一个模型并行组后，关键流量仍可在降级 SLO 内服务。</p><h3 id="_6-3-队列" tabindex="-1">6.3 队列 <a class="header-anchor" href="#_6-3-队列" aria-label="Permalink to &quot;6.3 队列&quot;">​</a></h3><p>排队可吸收短突发，不能创造容量。设置最大队列长度、等待 Deadline 和优先级；超过能力时快速拒绝或降级，防止所有请求都超时。</p><h2 id="_7-调度与扩缩" tabindex="-1">7. 调度与扩缩 <a class="header-anchor" href="#_7-调度与扩缩" aria-label="Permalink to &quot;7. 调度与扩缩&quot;">​</a></h2><h3 id="_7-1-指标选择" tabindex="-1">7.1 指标选择 <a class="header-anchor" href="#_7-1-指标选择" aria-label="Permalink to &quot;7.1 指标选择&quot;">​</a></h3><p>GPU 利用率对 LLM 服务可能滞后或误导。扩缩信号应组合排队长度/时长、活动序列、KV Cache、Goodput、TTFT 和到达率。</p><h3 id="_7-2-冷启动" tabindex="-1">7.2 冷启动 <a class="header-anchor" href="#_7-2-冷启动" aria-label="Permalink to &quot;7.2 冷启动&quot;">​</a></h3><p>加载几十 GB 权重可能需要数分钟。自动扩容必须提前量、最小热副本、快速制品分发或预测容量；靠请求到达后从零启动通常无法满足交互 SLO。</p><h3 id="_7-3-拓扑" tabindex="-1">7.3 拓扑 <a class="header-anchor" href="#_7-3-拓扑" aria-label="Permalink to &quot;7.3 拓扑&quot;">​</a></h3><p>模型并行副本需要整组 GPU 和合适互联，调度器必须避免碎片化。给单 Pod 请求 8 卡不代表它们自动位于同一高速互联域。</p><h2 id="_8-高可用与恢复" tabindex="-1">8. 高可用与恢复 <a class="header-anchor" href="#_8-高可用与恢复" aria-label="Permalink to &quot;8. 高可用与恢复&quot;">​</a></h2><h3 id="_8-1-故障域" tabindex="-1">8.1 故障域 <a class="header-anchor" href="#_8-1-故障域" aria-label="Permalink to &quot;8.1 故障域&quot;">​</a></h3><p>副本跨主机、机架或可用区分布，但跨区模型并行通信通常不合适。数据面与管理面、模型存储和网关分别评估故障。</p><h3 id="_8-2-健康与排流" tabindex="-1">8.2 健康与排流 <a class="header-anchor" href="#_8-2-健康与排流" aria-label="Permalink to &quot;8.2 健康与排流&quot;">​</a></h3><p>Readiness 只有模型完全可服务后通过；停止时先取消接流量，再等待有界时间完成或取消生成。强杀会造成流式中断和资源泄露。</p><h3 id="_8-3-制品与回滚" tabindex="-1">8.3 制品与回滚 <a class="header-anchor" href="#_8-3-制品与回滚" aria-label="Permalink to &quot;8.3 制品与回滚&quot;">​</a></h3><p>在多个位置保存验证过的镜像和模型制品，记录哈希与依赖。灾难恢复演练要实际从制品重建服务并跑探测，而不是只确认对象存储里有文件。</p><h2 id="_9-安全架构" tabindex="-1">9. 安全架构 <a class="header-anchor" href="#_9-安全架构" aria-label="Permalink to &quot;9. 安全架构&quot;">​</a></h2><ul><li>推理端点不直接暴露公网，经网关认证和限流；</li><li>管理、模型下载和推理网络分离；</li><li>运行时非特权、只读制品、最小云权限；</li><li>模型仓库、镜像和依赖做来源与漏洞检查；</li><li>Prompt/响应日志默认关闭全文或严格受控；</li><li>管理变更、模型加载和数据访问进入审计。</li></ul><p>Air Gap 环境还需规划制品导入、离线签名、漏洞库更新、时间同步和应急补丁流程。</p><h2 id="_10-成本模型" tabindex="-1">10. 成本模型 <a class="header-anchor" href="#_10-成本模型" aria-label="Permalink to &quot;10. 成本模型&quot;">​</a></h2><p>总成本包括 GPU/CPU/内存、存储、网络、电力、机房或云溢价、闲置冗余、许可证、工程与值班。按每个成功任务和满足 SLO 的 Goodput 计算，而不是只比较单卡小时价与托管 Token 单价。</p><p>利用率高能降低单位成本，但容量压得太紧会显著放大排队和故障。经济最优点必须服从业务 SLO 和风险容忍。</p><h2 id="_11-验收计划" tabindex="-1">11. 验收计划 <a class="header-anchor" href="#_11-验收计划" aria-label="Permalink to &quot;11. 验收计划&quot;">​</a></h2><ol><li>质量与安全：领域、工具、结构化输出和对抗集；</li><li>性能：真实长度分布下的阶梯并发与持续负载；</li><li>容量：峰值、突发、长上下文和一个副本故障；</li><li>可靠性：进程/主机故障、排流、重启和回滚；</li><li>恢复：从受信制品重建，验证 RTO/RPO；</li><li>安全：网络、权限、日志、供应链和管理面；</li><li>成本：按成功任务核算实际资源和人员。</li></ol><h2 id="_12-决策记录" tabindex="-1">12. 决策记录 <a class="header-anchor" href="#_12-决策记录" aria-label="Permalink to &quot;12. 决策记录&quot;">​</a></h2><p>最终决策应说明选用私有、托管或混合方案的约束，采用的模型/精度/引擎/硬件组合，基准数据，容量余量，N+1 策略，扩缩信号，成本假设，团队责任和复查条件。</p><p>私有化部署的正确问题不是“模型能不能跑起来”，而是“在一个故障域失效、真实流量突发和版本需要回滚时，系统是否仍能以可接受成本满足质量、安全与 SLO”。</p>`,80)])])}const b=e(l,[["render",s]]);export{u as __pageData,b as default};
